function text(value: unknown): string {
  return String(value ?? "").trim();
}

export function isFittingReplacementProductOffline(
  product: Record<string, unknown>
): boolean {
  const imagePath = text(
    product.imagePath || product.image || product.imageUrl
  ).toLowerCase();

  if (
    !imagePath ||
    imagePath.includes("placeholder") ||
    imagePath.includes("no-image") ||
    imagePath.includes("no_image") ||
    imagePath.includes("/images/logo/") ||
    imagePath.includes("foreach-logo") ||
    imagePath.includes("quick connector_200x200_01_v001.jpg")
  ) {
    return true;
  }

  if (product.showOnHome === false) return true;

  const status = text(product.status).toLowerCase();
  if (status && status !== "active") return true;

  return [
    product.productId,
    product.productCode,
    product.code,
    product.model,
    product.foreachModel,
    product.productModel,
  ]
    .map(text)
    .filter(Boolean)
    .some((key) => FITTING_REPLACEMENT_OFFLINE_PRODUCT_KEYS.has(key));
}
